//8*12??

void disp_ch(uint8 form, uint16 x, uint16 y,uint8 value,uint16 dcolor,uint16 bgcolor)	
{  
	uint16 i,j;
	uint8 const *temp ;//= chlibsmall;  
  uint16 cp = 0;
	uint16 pp = 0;
	uint16 cnum;
	
	if(form == FORM32X64)
		{
		temp = chlib;
		cp = 48; pp = 96;

		if(value == '-')
			temp += 10 * 576;	
		else if(value == ' ')
      temp += 11 * 576;			
		else	
			temp += (value - 48) * 576;	
	//	LCD_SetPos(x,x+47,y,y+119);
		}
	else
		{
		temp = chlibsmall;
		cp = 24; pp = 36;
		temp += (value - 32) * 108;		
		}
//	if(form == FORM32X64)	
		LCD_SetPos(x,x+cp-1,y,y+pp-1);
//	else
//		LCD_SetPos(x,x+14,y,y+pp-1);
	cnum = pp*cp/8 ;
	
  	
	for(j=0;j<cnum;j++)
		{
		for(i=0;i<8;i++)
			{ 		     
		 	if(((*temp >> i) & 0x01)!=0)
				{
				Write_Data(dcolor>>8,dcolor);
				} 
			else
				{
				Write_Data(bgcolor>>8,bgcolor);
				} 	
			}
		temp++;
		}
}

void disp_str(uint8 form, uint16 x,uint16 y,uint8 *str,uint16 dcolor,uint16 bgcolor)	  
{  
	unsigned int x1,y1;
	x1=x;
	y1=y;
	while(*str!='\0')
	{	
		
		disp_ch(form,x1,y1,*str,dcolor,bgcolor);
//		if(form == FORM48X120) //big form
//			x1+=47;
//		else			
//			x1+=15;	
			
		if(form == FORM32X64) //big form
			x1+=31;
		else
			x1+=23;	
		str++;
	}	
}

void disp_ch_16_24(uint8 form, uint16 x, uint16 y, uint8 value, uint16 dcolor, uint16 bgcolor)
{
	uint16 i, j;
	uint8 const *temp;//= chlibsmall;  
	uint16 cp = 0;
	uint16 pp = 0;
	uint16 cnum;

	if (form == FORM32X64)
	{
		temp = chlib;
		cp = 48; pp = 96;

		if (value == '-')
			temp += 10 * 576;
		else if (value == ' ')
			temp += 11 * 576;
		else
			temp += (value - 48) * 576;
	}
	else
	{
		temp = char_16_24;
		cp = 16; pp = 24;
		temp += (value - 32) * 48;
	}
	LCD_SetPos(x, x + cp - 1, y, y + pp - 1);
	cnum = pp*cp / 8;


	for (j = 0; j<cnum; j++)
	{
		for (i = 0; i<8; i++)
		{
			if (((*temp >> i) & 0x01) != 0)
			{
				Write_Data(dcolor >> 8, dcolor);
			}
			else
			{
				Write_Data(bgcolor >> 8, bgcolor);
			}
		}
		temp++;
	}
}

void disp_str_16_24(uint8 form, uint16 x, uint16 y, uint8 *str, uint16 dcolor, uint16 bgcolor)
{
	unsigned int x1, y1;
	x1 = x;
	y1 = y;
	while (*str != '\0')
	{

		disp_ch_16_24(form, x1, y1, *str, dcolor, bgcolor);
		if (form == FORM32X64) //big form
			x1 += 24;
		else
			x1 += 16;
		str++;
	}
}


