uint8 lcd_rotate_max;
uint8 lcd_rotate_index;

int16 mul_analog_input[10];
uint8  disp_item_queue[15];
extern uint16_t count_show_mstp_err;
//uint8 Disp_AI1[];
void Refresh_scroll(void)
{
	uint8 i,j;
	uint8 mode;
	memset(&scroll_ram[0][0],0,MAX_SCOROLL);
	//if(lcd_rotate_max > 9)
		lcd_rotate_max = 1;
	//lcd_rotate_index = 0;
	if(lcd_rotate_max > 0)
	{
		if((Modbus.com_config[0] == BACNET_SLAVE || Modbus.com_config[0] == BACNET_MASTER) && \
			(flag_mstp_err[0] == 1) && (count_show_mstp_err++ < 20) && (com_rx[0] > 100))
		{			
			memcpy(&scroll_ram[0][0],"Baud error      ",MAX_SCOROLL);
		}
		else if(SSID_Info.IP_Wifi_Status <= 1)
		{
			j = 0;
			scroll_ram[0][j++] = '2';
			scroll_ram[0][j++] = '0';
			scroll_ram[0][j++] =  Rtc.Clk.year / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.year % 10 + '0';
			scroll_ram[0][j++] = '-';
			scroll_ram[0][j++] =  Rtc.Clk.mon / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.mon % 10 + '0';
			scroll_ram[0][j++] = '-';
			scroll_ram[0][j++] =  Rtc.Clk.day / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.day % 10 + '0';
			scroll_ram[0][j++] = ' ';
			scroll_ram[0][j++] =  Rtc.Clk.hour / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.hour % 10 + '0';
			scroll_ram[0][j++] = ':';
			scroll_ram[0][j++] =  Rtc.Clk.min / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.min % 10 + '0';
			scroll_ram[0][j++] = ':';
			scroll_ram[0][j++] =  Rtc.Clk.sec / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.sec % 10 + '0';
			scroll_ram[0][j++] = ' ';
//			if(Daylight_Saving_Time)  // timezone : +8 ---> 800
//			{
//				if((Rtc.Clk.day_of_year >= 105) && (Rtc.Clk.day_of_year <= 260))
//				{
//					if(Rtc.Clk.hour < 23)
//					{
//						scroll_ram[0][j++] =  (Rtc.Clk.hour + 1) / 10 + '0';
//						scroll_ram[0][j++] =  (Rtc.Clk.hour + 1) % 10 + '0';
//					}
//					else
//					{
//						scroll_ram[0][j++] =  '0';
//						scroll_ram[0][j++] =  '0';
//					}
//				}
//					
//			}
		}
		else if(SSID_Info.IP_Wifi_Status == 2)
		{			
			sprintf(&scroll_ram[0][0],"%d.%d.%d.%d ",(uint8)SSID_Info.ip_addr[0],(uint8)SSID_Info.ip_addr[1],(uint8)SSID_Info.ip_addr[2], (uint8)SSID_Info.ip_addr[3]);
		}
		else if(SSID_Info.IP_Wifi_Status == 3)
		{
			memcpy(&scroll_ram[0][0],"wifi connected ",MAX_SCOROLL);
		}	
		else if(SSID_Info.IP_Wifi_Status == 4)
		{
			memcpy(&scroll_ram[0][0],"wifi disconnct ",MAX_SCOROLL);
		}		
		else if(SSID_Info.IP_Wifi_Status == 5)
		{
			memcpy(&scroll_ram[0][0],"wifi configure ",MAX_SCOROLL);
		}
	}

}

void display_scroll(void)
{
	uint8 cnt;
	uint8 i;
	
	//if(lcd_rotate_index == 0)
	{	
		Refresh_scroll();
	
		
	lcd_rotate_max = 1;
	if(lcd_rotate_max == 0)
	{
		for(i=0;i<10;i++)
			scroll_buf[i] = scroll_ram[lcd_rotate_max-1][i];
		scroll_buf[10] = '\0'; 
		disp_str(FORM15X30, 0,TIME_POS,scroll_buf,TSTAT8_CH_COLOR,TSTAT8_MENU_COLOR2); 
	}
	
	if(lcd_rotate_max > 0)
	{
		if(scroll >= &scroll_ram[lcd_rotate_max-1][1])
		{
			for(i=0;i<(&scroll_ram[lcd_rotate_max-1][MAX_SCOROLL - 1] - scroll + 1);i++)
				scroll_buf[i] = *(scroll+i);
			for(i=0;i<(scroll + MAX_SCOROLL - 1 - &scroll_ram[lcd_rotate_max-1][MAX_SCOROLL - 1]);i++)
				scroll_buf[&scroll_ram[lcd_rotate_max-1][MAX_SCOROLL- 1] - scroll + 1 + i] = scroll_ram[0][i];
		}
		else
		{
			for(i=0;i<10;i++)
				scroll_buf[i] = *(scroll+i);
		}
		if(scroll == &scroll_ram[lcd_rotate_max-1][MAX_SCOROLL - 1])
			scroll = &scroll_ram[0][0];	
		else	
			scroll++;
		
		scroll_buf[10] = '\0'; 
		disp_str(FORM15X30, 30,TIME_POS,scroll_buf,TSTAT8_CH_COLOR,TSTAT8_MENU_COLOR2); 
	}
}

	
}

uint8 const WRN_INFO[30] = {"Reverse AC supply is detected "}; 
uint8 const WRN_INFO_BACNET[30] = {"BACNET MSTP is detected "}; 
void scroll_warning(uint8 item)
{
	uint8 scroll_buf[11];
	uint8 i,j;
	static uint8 cnt = 0;
 
	disp_null_icon(239, 30, 0, 0,TIME_POS,0xf800, TSTAT8_MENU_COLOR2);
	for(i=0;i<10;i++)
	{
	 if(item == 0)	
		scroll_buf[i] = WRN_INFO[i + cnt];
	 else if(item == 1)
		scroll_buf[i] = WRN_INFO_BACNET[i + cnt];
	}
	scroll_buf[10] = '\0';
	disp_str(FORM15X30,30,TIME_POS,scroll_buf,0xf800,TSTAT8_MENU_COLOR2); 
  
	if(cnt < 25)
		cnt++;
	else
		cnt = 0;
	
}


